/*!
 * @file      lowpass_coeffs.h
 * @brief     Low-pass coefficients for the E01 FIR and IIR comparison.
 *
 *            Cut-off 2000 Hz at fs = 48000 Hz. FIR: 32 taps, hamming window, -6 dB at
 *            the cut-off. IIR: order 8 Butterworth, -3 dB at the cut-off, each
 *            section scaled to unity gain at DC.
 *
 *            Generated by `uv run coursework/E01-fir-iir/design.py`;
 *            edit the design there, not this file.
 */

#ifndef __LOWPASS_COEFFS_H__
#define __LOWPASS_COEFFS_H__

#include "dsp/biquad.h"

/*
 * FIR taps h[0] .. h[N-1]; symmetric, so linear phase with a
 * group delay of (N - 1) / 2 samples.
 */
#define LOWPASS_FIR_TAPS (32u)
extern const float LowpassFirCoeffs[LOWPASS_FIR_TAPS];

/*
 * IIR second-order sections, BIQUAD_COEFFS per section in the
 * order biquad.h expects, input section first.
 */
#define LOWPASS_IIR_SECTIONS (4u)
extern const float LowpassIirSos[LOWPASS_IIR_SECTIONS * BIQUAD_COEFFS];

#endif /* __LOWPASS_COEFFS_H__ */
